const fs = require('node:fs')
const { inspectTemplate } = require('./panel-template-instrumentation')
const { validatedVisualBindings } = require('./panel-visual-bindings')
const { listCatalogDevices, listCatalogTargets } = require('./control-catalog')
const { configuredRoutes } = require('./control-bound-protocol')
const { provisionManagedBridges } = require('./managed-native-bridge')
const { backupFlow, flowLocation, runtimeDirectory } = require('./managed-bridge-admin')
const { loopbackFetch } = require('./panel-http')

const snapshotCache = new Map()

function snapshotCacheKey (localPort, adminRoot) {
  return `${localPort}:${adminRoot}`
}

function conflict (message) {
  const error = new Error(message)
  error.status = 409
  return error
}

function adminUrl (localPort, adminRoot = '/red') {
  if (!Number.isInteger(localPort) || localPort < 1 || localPort > 65535) {
    throw new Error('Node-RED runtime port unavailable')
  }
  if (typeof adminRoot !== 'string' || !adminRoot.startsWith('/') || /[?#]/.test(adminRoot)) {
    throw new Error('Node-RED admin root unavailable')
  }
  const url = new URL(`http://127.0.0.1:${localPort}`)
  url.pathname = adminRoot.replace(/\/$/, '') + '/flows'
  return url.href
}

async function getSnapshot (localPort, fetcher = loopbackFetch, adminRoot = '/red', options = {}) {
  const key = snapshotCacheKey(localPort, adminRoot)
  const cached = snapshotCache.get(key)
  const now = Date.now()
  if (cached && typeof options.expectedRev === 'string' && cached.snapshot.rev === options.expectedRev) {
    return cached.snapshot
  }
  if (cached && Number.isFinite(options.maxAgeMs) && now - cached.time <= options.maxAgeMs) {
    return cached.snapshot
  }
  try {
    const response = await fetcher(adminUrl(localPort, adminRoot), {
      headers: { 'Node-RED-API-Version': 'v2' },
      signal: AbortSignal.timeout(10000)
    })
    if (!response.ok) throw new Error(`Automator Flow read failed (${response.status})`)
    const snapshot = await response.json()
    if (typeof snapshot.rev !== 'string' || !Array.isArray(snapshot.flows)) {
      throw new Error('Automator did not return a versioned Flow')
    }
    snapshotCache.set(key, { snapshot, time: Date.now() })
    return snapshot
  } catch (error) {
    const isTimeout = error?.name === 'TimeoutError' || error?.code === 'ABORT_ERR' ||
      /aborted.*timeout/i.test(String(error?.message || ''))
    if (isTimeout && cached && Number.isFinite(options.allowStaleMs) &&
      Date.now() - cached.time <= options.allowStaleMs) {
      return cached.snapshot
    }
    if (isTimeout) throw new Error('Automator Flow is still restarting; retry in a moment')
    throw error
  }
}

function findPanel (snapshot, panelId) {
  const panel = snapshot.flows.find(node => node.id === panelId)
  if (!panel || panel.type !== 'ui-control-panel') {
    throw conflict('Visual editor is not enabled for this panel')
  }
  if (String(panel.z || '').startsWith('subflow:') ||
    snapshot.flows.some(node => node.id === panel.z && node.type === 'subflow')) {
    throw conflict('Editing a shared subflow template from the page is not supported')
  }
  return panel
}

function editorConfig (snapshot, panelId) {
  const panel = findPanel(snapshot, panelId)
  const inspected = inspectTemplate(panel.format)
  let bindings = panel.visualBindings || '{}'
  if (typeof bindings === 'string') bindings = JSON.parse(bindings)
  return {
    rev: snapshot.rev,
    templateHash: inspected.templateHash,
    candidates: inspected.candidates,
    bindings: Object.entries(bindings).map(([id, entry]) => ({ id, ...entry })),
    room: panel.boundRoom || ''
  }
}

async function applyVisualBindings ({
  panelId, rev, templateHash, entries, userDir, localPort, adminRoot = '/red',
  catalogBase, editorCookie, fetcher = loopbackFetch, flowAccess,
  measure = (_name, operation) => operation()
}) {
  // The editor authenticates the browser; Flow access stays on the runtime's loopback interface.
  const directory = runtimeDirectory(userDir)
  if (!catalogBase) throw conflict('Device catalog is unavailable')
  if (!Array.isArray(entries) || entries.length > 256) throw conflict('Invalid binding draft')
  const [snapshot, devices] = await Promise.all([
    measure('flow-read', () => flowAccess ? flowAccess.getSnapshot() : getSnapshot(localPort, fetcher, adminRoot, { expectedRev: rev })),
    measure('catalog-devices', () => listCatalogDevices(catalogBase, fetcher))
  ])
  if (snapshot.rev !== rev) throw conflict('Flow changed; refresh the visual editor')
  const panel = findPanel(snapshot, panelId)
  if (inspectTemplate(panel.format).templateHash !== templateHash) {
    throw conflict('Template changed; refresh the visual editor')
  }
  const location = flowLocation(directory)
  if (JSON.stringify(JSON.parse(fs.readFileSync(location.flowFile, 'utf8'))) !== JSON.stringify(snapshot.flows)) {
    throw conflict('Deployed Flow differs from the active project file')
  }

  const deviceIds = [...new Set(entries.map(entry => entry?.device))]
  for (const id of deviceIds) {
    if (!devices.some(device => device.id === id && device.online)) {
      throw conflict(`Device is unavailable: ${id}`)
    }
  }
  const targetsByDevice = new Map(await measure('catalog-targets', () => Promise.all(deviceIds.map(async id =>
    [id, await listCatalogTargets(catalogBase, id, fetcher)]))))
  const validated = measure('validate', () => validatedVisualBindings({ format: panel.format, entries, devices, targetsByDevice }))
  const next = structuredClone(snapshot.flows)
  const nextPanel = next.find(node => node.id === panelId)
  nextPanel.visualBindings = JSON.stringify(validated)
  nextPanel.nativeBridge = configuredRoutes(nextPanel).size > 0
  const provisioned = measure('bridge', () => provisionManagedBridges(next, { panelId }))

  if (JSON.stringify(JSON.parse(fs.readFileSync(location.flowFile, 'utf8'))) !== JSON.stringify(snapshot.flows)) {
    throw conflict('Active project changed during validation')
  }
  // Node order is not a Flow change. An unchanged draft must not restart the
  // panel and its bridge just because provisioning moved generated nodes.
  const currentNodes = new Map(snapshot.flows.map(node => [node.id, node]))
  if (currentNodes.size === snapshot.flows.length && provisioned.flows.length === snapshot.flows.length &&
    provisioned.flows.every(node => JSON.stringify(node) === JSON.stringify(currentNodes.get(node.id)))) {
    return {
      ok: true,
      rev: snapshot.rev,
      updated: [],
      unchanged: true,
      editorConfig: editorConfig(snapshot, panelId),
      devices
    }
  }
  const backupDir = measure('backup', () => backupFlow(location, snapshot.rev, snapshot.flows))
  let applied
  if (flowAccess) {
    applied = await measure('deploy', () => flowAccess.setSnapshot({ rev: snapshot.rev, flows: provisioned.flows }))
  } else {
    const response = await measure('deploy', () => fetcher(adminUrl(localPort, adminRoot), {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Node-RED-API-Version': 'v2',
        'Node-RED-Deployment-Type': 'nodes'
      },
      body: JSON.stringify({ rev: snapshot.rev, flows: provisioned.flows }),
      signal: AbortSignal.timeout(20000)
    }))
    if (!response.ok) throw conflict(`Automator rejected the binding update (${response.status})`)
    applied = await response.json().catch(() => ({}))
  }
  // The v2 Flow POST is the runtime acknowledgement. Avoid rereading the
  // complete Flow repeatedly while modified nodes are still restarting.
  const appliedRev = typeof applied.rev === 'string' ? applied.rev : snapshot.rev
  snapshotCache.set(snapshotCacheKey(localPort, adminRoot), {
    snapshot: { rev: appliedRev, flows: provisioned.flows },
    time: Date.now()
  })
  // Session readiness is restored by bounded browser retries, not another
  // blocking loopback request while the node is being replaced.
  return {
    ok: true,
    rev: appliedRev,
    backupDir,
    updated: provisioned.updated,
    editorConfig: editorConfig({ rev: appliedRev, flows: provisioned.flows }, panelId),
    devices
  }
}

module.exports = { adminUrl, applyVisualBindings, editorConfig, getSnapshot }
